WITH base AS (SELECT * FROM stores WHERE region IN ('West', 'North', 'South') AND city IN ('Singapore', 'London', 'Bangkok')), city_summary AS (SELECT city, region, COUNT(DISTINCT sqft) unique_regions, MIN(sqft) min_sqft FROM base GROUP BY city, region) SELECT city, region, unique_regions, min_sqft FROM city_summary WHERE unique_regions > 4 ORDER BY unique_regions DESC, city DESC, region LIMIT 5
